sys_variable_value.value:
(function() {
    try {
        var doc = JSON.parse(adf_document);
        var newNodes = JSON.parse(content_to_append);

        if (!doc.content) {
            doc.content = [];
        }

        if (!Array.isArray(newNodes)) {
            newNodes = [newNodes];
        }

        if (insert_position === 'start') {
            doc.content = newNodes.concat(doc.content);
        } else {
            // Default to 'end'
            doc.content = doc.content.concat(newNodes);
        }

        adf_document = JSON.stringify(doc);
    } catch (e) {
        gs.error('Append Content to ADF: Failed to parse or merge JSON - ' + e.message);
        // Return the original document unchanged on error
    }
})();

